parameters.query:
SELECT COUNT(*) as total
FROM tracker_entries
WHERE person_id = '{{ $("SYS_BuildInputContext").first().json.person_id }}'::uuid;

parameters.jsCode:
let raw = $input.first().json.output || "";

raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    entry_type: "note",
    tags: [],
    summary: "parse fallback",
    error: e.message
  };
}

const sourceText = ($('SYS_BuildInputContext').first().json.text || "").trim();
const lower = sourceText.toLowerCase();
const activityMap = [
  { pattern: /^(английский|english)\s+(\d{1,3})\b/i, code: "english" },
  { pattern: /^(лёд|лед|ice)\s+(\d{1,3})\b/i, code: "ice" },
  { pattern: /^(дриблинг|dribbling|dribble)\s+(\d{1,3})\b/i, code: "dribbling" }
];

let activity = null;
for (const item of activityMap) {
  const match = lower.match(item.pattern);
  if (match) {
    activity = {
      activity_type_code: item.code,
      duration_minutes: Number(match[2])
    };
    break;
  }
}

const allowedTrackerTypes = new Set([
  "note",
  "idea",
  "insight",
  "decision",
  "observation",
  "hypothesis",
  "task",
  "feeling"
]);

if (!allowedTrackerTypes.has(parsed.entry_type)) {
  parsed.entry_type = "note";
}

const trajectoryTypeMap = {
  note: "general_note",
  idea: "general_note",
  decision: "general_note",
  hypothesis: "general_note",
  task: "general_note",
  observation: "observation",
  insight: "insight",
  feeling: "feeling"
};

return [{
  json: {
    ...parsed,
    is_activity_event: Boolean(activity),
    activity_type_code: activity?.activity_type_code || null,
    duration_minutes: activity?.duration_minutes || null,
    trajectory_entry_type: trajectoryTypeMap[parsed.entry_type] || "general_note"
  }
}];

const entries = $input.all();

if (entries.length === 0) {
  return [{
    json: {
      reply: 'Пока нет сохранённых записей.'
    }
  }];
}

const lines = entries.map(entry => {
  const icon =
    entry.json.entry_type === 'observation' ? '🧭' :
    entry.json.entry_type === 'insight' ? '💡' :
    '•';

  return `${icon} ${entry.json.content}`;
});

return [{
  json: {
    reply:
      'Последние записи:\n\n' +
      lines.join('\n\n')
  }
}];

const rawText = $json.text || "";
const text = rawText.trim();

if (!text) {
  throw new Error("No text available");
}

if (text.startsWith("/")) {
  return [{
    json: {
      route: "command",
      text: text.startsWith("/help") ? "/start" : text
    }
  }];
}

return [{
  json: {
    route: "tracker",
    text
  }
}];

let voiceText = "";

try {
  voiceText = $('VOI_NormalizeTranscript').first().json.text;
} catch (e) {
  voiceText = "";
}

const telegramText =
  $('TG_Trigger').first()?.json?.message?.text || "";

return [{
  json: {
    text: voiceText || telegramText,
    person_id: $json.person_id,
    conversation_id: $json.conversation_id,
    trajectory_id: $json.trajectory_id,
    current_stage: $json.current_stage,
    sub_stage: $json.sub_stage,
    pattern_type: $json.pattern_type,
    allow_reminders: $json.allow_reminders
  }
}];

let raw = $input.first().json.output || "";
// Remove markdown fences like ```json ... ```.
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();
try {
  return [{ json: JSON.parse(raw) }];
} catch (e) {
  return [{ json: { has_signal: false, error: "Invalid JSON structure" } }];
}

const total = Number($json.total ?? $('TRK_GetEntryCount').first().json.total ?? 0);
const personId = String($('SYS_BuildInputContext').first().json.person_id ?? '');

const confirmations = [
  '🧭 Записал.',
  '✅ Сохранил.',
  '👍 Есть.',
  '🎯 Поймал момент.',
  '🏒 Принял.'
];

const shortQuestions = [
  'Что чувствовал?',
  'Было легко?',
  'Где стало сложно?',
  'Что помогло начать?',
  'Сам заметил?'
];

const missions = [
  '🏅 Наблюдатель +1. Поймай ещё один момент.',
  '✅ Записал. Миссия: заметить момент перед стартом.',
  '🎯 Поймай момент, когда не хотелось начинать.'
];

const gpsSignalQuestions = [
  '🏒 Что сегодня сделал без напоминаний?',
  '⚡ В какой момент было больше всего энергии?',
  '🎯 Что оказалось сложнее, чем ожидал?',
  '🧭 Что помогло не бросить?',
  '🚀 Что захотелось сделать самому?'
];

const deepQuestions = [
  ['🏒 Уже 5 наблюдений.', 'Что помогает тебе двигаться вперёд даже когда не хочется?'],
  ['🏒 Уже 15 наблюдений.', 'Что ты стал делать чаще без напоминаний?'],
  ['🧭 Уже 30 наблюдений.', 'Что ты чаще всего замечаешь за собой?'],
  ['🏒 Уже 50 наблюдений.', 'Где стало больше самостоятельности?'],
  ['🚀 Уже 75 наблюдений.', 'Что теперь запускаешь сам?'],
  ['🧭 Уже 100 наблюдений.', 'Что ты понял про себя как игрока?']
];

function milestoneLines(count) {
  const milestones = [5, 15, 30, 50, 75, 100];
  const exact = milestones.indexOf(count);
  if (exact !== -1) return deepQuestions[exact];
  if (count > 100 && count % 50 === 0) {
    return [`🧭 Уже ${count} наблюдений.`, 'Что ты понял про себя как игрока?'];
  }
  return null;
}

let hash = total * 37;
for (const ch of personId) hash = (hash + ch.charCodeAt(0)) % 1000;
const roll = hash % 100;
const milestone = milestoneLines(total);

let lines;
let replyType;

if (milestone) {
  lines = milestone;
  replyType = 'deep';
} else if (total >= 20 && roll >= 96) {
  lines = [gpsSignalQuestions[(total + roll) % gpsSignalQuestions.length]];
  replyType = 'gps_signal_question';
} else if (roll < 70) {
  lines = [confirmations[total % confirmations.length]];
  replyType = 'confirmation';
} else if (roll < 90) {
  lines = [shortQuestions[total % shortQuestions.length]];
  replyType = 'short_question';
} else {
  lines = [missions[total % missions.length]];
  replyType = 'mission';
}

return [{
  json: {
    ...$json,
    reply_text: lines.join('\n\n'),
    reflection_total: total,
    reflection_type: replyType,
    reflection_deep: replyType === 'deep'
  }
}];
